#include <stdio.h>
int main(void) {
    int arr[] = {1, 2, 3, 4, 5};
    int sum = 0;
    for (int i = 0; i < 5; i++) sum += arr[i];
    printf("%d\n", sum);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {4, 2, 7, 1, 9};
    int target = 7, idx = -1;
    for (int i = 0; i < 5; i++) {
        if (arr[i] == target) { idx = i; break; }
    }
    printf("%d\n", idx);
    return 0;
}

