    int arr[] = {10, 20, 30, 40, 50};
    for (int i = 4; i >= 0; i--) printf("%d ", arr[i]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {5, 10, 15, 20};
    int s = 0;
    for (int i = 0; i < 4; i++) s += arr[i] * i;
    printf("%d\n", s);
    return 0;
}

#include <stdio.h>
int main(void) {
    int prices[] = {7, 1, 5, 3, 6, 4};
    int minP = prices[0], maxProfit = 0;
    for (int i = 1; i < 6; i++) {
        if (prices[i] - minP > maxProfit) maxProfit = prices[i] - minP;
        if (prices[i] < minP) minP = prices[i];
    }
    printf("%d\n", maxProfit);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {1, 2, 3, 4, 5};
    int n = 5, k = 2;
    int rotated[5];
    for (int i = 0; i < n; i++) rotated[(i + k) % n] = arr[i];
    for (int i = 0; i < n; i++) printf("%d ", rotated[i]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {1, 1, 2, 3, 3, 5};
    int distinct = 1;
    for (int i = 1; i < 6; i++) {
        if (arr[i] != arr[i - 1]) distinct++;
    }
    printf("%d\n", distinct);
    return 0;
}

#include <stdio.h>
int main(void) {
    int arr[] = {3, 1, 4, 1, 5};
    int prefix[6];
    prefix[0] = 0;
    for (int i = 0; i < 5; i++) prefix[i + 1] = prefix[i] + arr[i];
    printf("%d\n", prefix[4] - prefix[1]);
    return 0;
}
